definition.script:
// Bootstrap only. Real pipeline: franklin/deploy/jenkins/calendar-publisher.groovy
node {
    stage('Sync repo') {
        // reset --hard, not pull: this checkout is a deploy reference, and a
        // fast-forward pull reads FETCH_HEAD, which concurrent fetches corrupt.
        // The groovy is copied INTO the workspace via sal, so the jenkins user
        // needs no read access to the checkout.
        sh '''#!/bin/bash
set -euo pipefail
R=/home/Franklin/franklin-radicale
sudo -u sal -H git -C "$R" fetch origin --prune
sudo -u sal -H git -C "$R" checkout -q franklin_1.0prod
sudo -u sal -H git -C "$R" reset -q --hard origin/franklin_1.0prod
sudo -u sal -H git -C "$R" log -1 --format='publisher rev: %h %ci %s'
sudo -u sal -H cat "$R/franklin/deploy/jenkins/calendar-publisher.groovy" > calendar-publisher.groovy
'''
    }
    load('calendar-publisher.groovy').run(params)
}
